/* ════════════════════════════════════════════════════════════════════════════ */
export default function App() {
  const [data, setData] = useState(EMBEDDED);
  const [tab, setTab] = useState("panorama");
  const [year, setYear] = useState(Y1);
  const [playing, setPlaying] = useState(false);
  const [filtro, setFiltro] = useState("todos");
  const [selCaso, setSelCaso] = useState(null);
  const [provSel, setProvSel] = useState(null);
  const [frente, setFrente] = useState("rusia"); // carne de cañón: rusia | angola
  const [votos, setVotos] = useState(() => lsGet(LS_VOTED, {}));
  const [live, setLive] = useState({});
  const playRef = useRef(null);

  useEffect(() => {
    const id = "smo-fonts";
    if (!document.getElementById(id)) {
      const l = document.createElement("link");
      l.id = id; l.rel = "stylesheet";
      l.href = "https://fonts.googleapis.com/css2?family=Archivo:wght@500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600&display=swap";
      document.head.appendChild(l);
    }
  }, []);

  useEffect(() => {
    let alive = true;
    fetch(DATA_URL).then((r) => (r.ok ? r.json() : null)).then((j) => { if (alive && j) setData(j); }).catch(() => {});
    return () => { alive = false; };
  }, []);

  useEffect(() => { pollStore.results().then(setLive).catch(() => setLive({})); }, []);

  useEffect(() => {
    if (!playing) { if (playRef.current) clearInterval(playRef.current); return; }
    playRef.current = setInterval(() => {
      setYear((y) => { if (y >= Y1) { setPlaying(false); return Y1; } return y + 1; });
    }, 90);
    return () => { if (playRef.current) clearInterval(playRef.current); };
  }, [playing]);

  const vote = useCallback(async (qid, oid) => {
    if (votos[qid]) return;
    const nv = { ...votos, [qid]: oid }; setVotos(nv); lsSet(LS_VOTED, nv);
    setLive((p) => { const c = { ...p, [qid]: { ...(p[qid] || {}) } }; c[qid][oid] = (c[qid][oid] || 0) + 1; return c; });
    try { await pollStore.vote(qid, oid); } catch {}
  }, [votos]);

  const kpi = (id) => (data.kpis || []).find((k) => k.id === id) || {};
  const caidos = useMemo(() => data.caidos || [], [data]);
  const resumen = useMemo(() => data.resumen || { categorias: [] }, [data]);
  const sistema = useMemo(() => data.sistema || { leyes: [], cargas: [] }, [data]);
  const cc = useMemo(() => data.carneCanon || { angola: {}, rusia: {} }, [data]);

  const caidosFiltrados = useMemo(
    () => caidos.filter((c) => filtro === "todos" || c.cat === filtro), [caidos, filtro]
  );

  // donut de causas
  const donut = useMemo(
    () => (resumen.categorias || []).map((k) => ({ id: k.id, name: CAT[k.id] ? CAT[k.id].l : k.etiqueta, value: k.n })),
    [resumen]
  );

  // timeline: agrupa por año y apila
  const tl = useMemo(() => {
    const byYear = {};
    for (const c of caidos) { const y = yearOf(c.fecha); (byYear[y] = byYear[y] || []).push(c); }
    const out = [];
    Object.keys(byYear).forEach((y) => {
      byYear[y].sort((a, b) => CAT_ORDER.indexOf(a.cat) - CAT_ORDER.indexOf(b.cat));
      byYear[y].forEach((c, i) => out.push({ ...c, y: +y, stack: i }));
    });
    return out;
  }, [caidos]);
  const maxStack = useMemo(() => Math.max(0, ...tl.map((d) => d.stack)), [tl]);
  const reveladosN = useMemo(() => caidosFiltrados.filter((c) => yearOf(c.fecha) <= year).length, [caidosFiltrados, year]);

  // mapa
  const provCount = useMemo(() => {
    const acc = {};
    for (const c of caidosFiltrados) if (c.prov) acc[c.prov] = (acc[c.prov] || 0) + 1;
    return acc;
  }, [caidosFiltrados]);
  const maxProv = Math.max(1, ...Object.values(provCount));
  const provFill = (code) => {
    const v = provCount[code];
    if (!v) return "rgba(224,240,228,.045)";
    const t = 0.16 + 0.6 * Math.sqrt(v / maxProv);
    return `rgba(51,194,122,${t.toFixed(3)})`;
  };
  const sinProv = caidosFiltrados.filter((c) => !c.prov).length;
  const provCasos = provSel ? caidosFiltrados.filter((c) => c.prov === provSel) : [];

  const menoresN = useMemo(() => caidos.filter((c) => c.menor).length, [caidos]);
  const caso = selCaso ? caidos.find((c) => c.id === selCaso) : null;

  // geometría timeline
  const TL = { W: 1000, ML: 40, MR: 20, TOP: 16, GAP: 13, R: 4.6 };
  const plotW = TL.W - TL.ML - TL.MR;
  const baseY = TL.TOP + (maxStack + 1) * TL.GAP;
  const TL_H = baseY + 34;
  const tlX = (yr) => TL.ML + ((yr - Y0) / (Y1 - Y0)) * plotW;
  const tlY = (stack) => baseY - stack * TL.GAP;
  const DECADAS = [1964, 1970, 1980, 1990, 2000, 2010, 2020, 2023];

  const TABS = [
    ["panorama", "Panorama"], ["caidos", "Los caídos"], ["mapa", "El mapa"],
    ["maquina", "La máquina"], ["canon", "Carne de cañón"], ["encuesta", "Tu lectura"],
  ];

  const MAP = { W: 774.25848, H: 264.93973 };

  return (
    <div className="smo">
      <style>{CSS}</style>

      <header className="hd">
        <div className="eyebrow">DERECHOS · SERVICIO MILITAR OBLIGATORIO · {data.meta && data.meta.periodo}</div>
        <h1 className="title">SERVIR<span> O MORIR</span></h1>
        <p className="sub">
          El servicio militar obligatorio cubano es, según Archivo Cuba, <b>trata de personas con un
          costo letal</b>: recluta a menores, los explota como mano de obra y castiga la huida hasta con
          la muerte. En caso de guerra, es una reserva cautiva de más de un millón de jóvenes.
        </p>
        <div className="kpis">
          {["caidos", "reserva", "angola", "mercenarios"].map((id) => (
            <div className="kpi" key={id}>
              <div className="kpi-n">{fmt(kpi(id).valor)}</div>
              <div className="kpi-l">{kpi(id).etiqueta}</div>
              {kpi(id).sufijo && <div className="kpi-s">{kpi(id).sufijo}</div>}
            </div>
          ))}
        </div>
        {data.meta && data.meta.advertencia && <div className="warn">⚠ {data.meta.advertencia}</div>}
        <div className="stamp">FUENTE · {data.meta && data.meta.fuentePrincipal} · act. {data.meta && data.meta.actualizado}</div>
      </header>

      <nav className="tabs">
        {TABS.map(([k, lbl]) => (
          <button key={k} className={"tab" + (tab === k ? " on" : "")} onClick={() => setTab(k)}>{lbl}</button>
        ))}
      </nav>

      {/* ══ 1 · PANORAMA ══ */}
      {tab === "panorama" && (
        <section className="panel">
          <div className="grid2">
            <div className="card">
              <div className="card-h">54 muertes, clasificadas</div>
              <div className="card-sub">{resumen.nota}</div>
              <div className="chart">
                <ResponsiveContainer width="100%" height={250}>
                  <PieChart>
                    <Pie data={donut} dataKey="value" nameKey="name" cx="50%" cy="50%"
                      innerRadius={60} outerRadius={96} paddingAngle={2} stroke="#0A0F0C" strokeWidth={2}
                      onClick={(d) => d && d.id && setFiltro(filtro === d.id ? "todos" : d.id)}>
                      {donut.map((d) => <Cell key={d.id} cursor="pointer" fill={catCol(d.id)}
                        fillOpacity={filtro === "todos" || filtro === d.id ? 1 : 0.35} />)}
                    </Pie>
                    <Tooltip content={<CatTip />} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
              <div className="legend">
                {(resumen.categorias || []).map((k) => (
                  <button key={k.id} className={"lg-btn" + (filtro === k.id ? " on" : "")}
                    onClick={() => setFiltro(filtro === k.id ? "todos" : k.id)}>
                    <i style={{ background: catCol(k.id) }} />{CAT[k.id] ? CAT[k.id].s : k.etiqueta} · <b>{k.n}</b>
                  </button>
                ))}
              </div>
            </div>
            <div className="card">
              <div className="card-h">El registro es la punta del iceberg</div>
              <div className="card-sub">Sin cifras oficiales, la fuente cree que el costo real es de cientos o miles.</div>
              <div className="ice">
                <div className="ice-top">
                  <div className="ice-n">54</div>
                  <div className="ice-l">documentados<br />con datos suficientes</div>
                </div>
                <div className="ice-water" />
                <div className="ice-deep">
                  <div className="ice-deep-t">cientos · quizás miles</div>
                  <div className="ice-deep-s">sin documentar en seis décadas de SMO (adicional a Angola)</div>
                </div>
              </div>
              <div className="mini-stats">
                <div><b className="men">{menoresN}</b> eran menores de edad</div>
                <div><b>2</b> de solo 2 países que obligan a servir a menores (con Corea del Norte)</div>
              </div>
            </div>
          </div>
          <div className="readout">
            <p><b>Trata de personas perpetrada por el Estado.</b> El informe sostiene que el trabajo forzoso
              es intrínseco al servicio militar cubano, con dos agravantes: se explota a menores y se coacciona
              la «donación» de sangre. Siendo el propio Estado el perpetrador, no hay protección ni remedio para
              las víctimas. Y en el horizonte, la guerra: una <b>reserva cautiva</b> de más de un millón de
              varones jóvenes, ya entrenados.</p>
          </div>
        </section>
      )}

      {/* ══ 2 · LOS CAÍDOS (timeline) ══ */}
      {tab === "caidos" && (
        <section className="panel">
          <div className="card-h">Seis décadas, mes a mes se repite</div>
          <div className="card-sub">
            Cada punto es una persona, en su año y coloreada por causa de muerte. Reproduce o arrastra;
            filtra por causa. La concentración de los últimos años refleja, sobre todo, que ahora se documenta más.
          </div>
          <div className="map-bar">
            <button className="play" onClick={() => setPlaying((p) => !p)}>{playing ? "❚❚ Pausa" : "▶ Reproducir"}</button>
            <input className="scrub" type="range" min={Y0} max={Y1} value={year}
              onChange={(e) => { setPlaying(false); setYear(Number(e.target.value)); }} />
            <div className="year-box">
              <span className="year-n">{year}</span>
              <span className="year-l">{reveladosN} de {caidosFiltrados.length} hasta {year}</span>
            </div>
          </div>
          <div className="chips">
            <button className={"chip" + (filtro === "todos" ? " on" : "")} onClick={() => setFiltro("todos")}>Todas · {caidos.length}</button>
            {CAT_ORDER.map((k) => {
              const n = caidos.filter((c) => c.cat === k).length;
              if (!n) return null;
              return (
                <button key={k} className={"chip" + (filtro === k ? " on" : "")}
                  style={filtro === k ? { background: CAT[k].c, borderColor: CAT[k].c, color: "#0a0f0c" } : { borderColor: CAT[k].c + "66", color: CAT[k].c }}
                  onClick={() => setFiltro(filtro === k ? "todos" : k)}>{CAT[k].s} · {n}</button>
              );
            })}
          </div>
          <div className="tl-wrap">
            <svg viewBox={`0 0 ${TL.W} ${TL_H}`} className="tl-svg" preserveAspectRatio="xMidYMax meet">
              <line x1={TL.ML} y1={baseY + 6} x2={TL.W - TL.MR} y2={baseY + 6} stroke="rgba(224,240,228,.12)" />
              {DECADAS.map((yr) => (
                <g key={yr}>
                  <line x1={tlX(yr)} y1={TL.TOP} x2={tlX(yr)} y2={baseY + 6} stroke="rgba(224,240,228,.05)" />
                  <text x={tlX(yr)} y={TL_H - 8} textAnchor="middle" className="tl-mes">{yr}</text>
                </g>
              ))}
              <line x1={tlX(year)} y1={TL.TOP} x2={tlX(year)} y2={baseY + 6}
                stroke={C.green} strokeWidth={1.4} strokeDasharray="3 3" opacity={year < Y1 ? 0.85 : 0} />
              {tl.map((c) => {
                const dim = filtro !== "todos" && c.cat !== filtro;
                const revealed = c.y <= year;
                const on = selCaso === c.id;
                const x = tlX(c.y), yy = tlY(c.stack);
                return (
                  <g key={c.id} onClick={() => setSelCaso(c.id)} style={{ cursor: "pointer" }}
                    opacity={dim ? 0.1 : (revealed ? 1 : 0.18)}>
                    {c.menor && <circle cx={x} cy={yy} r={TL.R + 2.4} fill="none" stroke={C.greenHi} strokeWidth={1} />}
                    <circle cx={x} cy={yy} r={on ? TL.R + 1.6 : TL.R} fill={catCol(c.cat)}
                      stroke={on ? "#fff" : "#0A0F0C"} strokeWidth={on ? 1.3 : 0.6} />
                  </g>
                );
              })}
            </svg>
          </div>
          <div className="tl-key">
            <span><i className="k-ring" /> menor de edad</span>
            <span className="tl-key-mut">altura = casos del mismo año · color = causa</span>
          </div>
          {caso ? <CasoCard caso={caso} onClose={() => setSelCaso(null)} /> :
            <div className="tl-hint">Toca un punto de la línea para leer el caso.</div>}
        </section>
      )}

      {/* ══ 3 · MAPA ══ */}
      {tab === "mapa" && (
        <section className="panel">
          <div className="card-h">Dónde caen</div>
          <div className="card-sub">Intensidad = casos documentados por provincia. Filtra por causa; toca una provincia encendida.</div>
          <div className="chips">
            <button className={"chip" + (filtro === "todos" ? " on" : "")} onClick={() => setFiltro("todos")}>Todas</button>
            {CAT_ORDER.map((k) => {
              const n = caidos.filter((c) => c.cat === k).length; if (!n) return null;
              return (
                <button key={k} className={"chip" + (filtro === k ? " on" : "")}
                  style={filtro === k ? { background: CAT[k].c, borderColor: CAT[k].c, color: "#0a0f0c" } : { borderColor: CAT[k].c + "66", color: CAT[k].c }}
                  onClick={() => setFiltro(filtro === k ? "todos" : k)}>{CAT[k].s}</button>
              );
            })}
          </div>
          <div className="map-stage">
            <div className="map-wrap">
              <svg viewBox={`0 0 ${MAP.W} ${MAP.H}`} className="map-svg" preserveAspectRatio="xMidYMid meet">
                {Object.entries(PROV_PATHS).map(([code, d]) => (
                  <path key={code} d={d} fill={provFill(code)}
                    stroke={provSel === code ? C.greenHi : "rgba(224,240,228,.16)"} strokeWidth={provSel === code ? 1.2 : 0.5}
                    style={{ cursor: provCount[code] ? "pointer" : "default" }}
                    onClick={() => provCount[code] && setProvSel(provSel === code ? null : code)} />
                ))}
              </svg>
            </div>
            <aside className="map-detail">
              {provSel ? (
                <>
                  <div className="md-year">{PROV_NOMBRE[provSel]}</div>
                  <div className="md-toll"><span className="md-toll-n">{provCount[provSel]}</span><span className="md-toll-l">caídos documentados</span></div>
                  <div className="prov-list">
                    {provCasos.map((c) => (
                      <button key={c.id} className="pl-row" onClick={() => setSelCaso(c.id)}>
                        <i style={{ background: catCol(c.cat) }} />
                        <span className="pl-name">{c.menor ? "• " : ""}{c.nombre}</span>
                        <span className="pl-date">{yearOf(c.fecha)}</span>
                      </button>
                    ))}
                  </div>
                </>
              ) : (
                <>
                  <div className="md-year">Panorama</div>
                  <p className="md-txt">
                    Las unidades de <b>La Habana</b>, <b>Matanzas</b> y <b>Mayabeque</b> concentran los casos
                    documentados; los clústeres (Matanzas 2022, San Miguel de los Baños 2005) corresponden a
                    incidentes únicos con varias víctimas. Toca una provincia para ver sus caídos.
                  </p>
                  {sinProv > 0 && <div className="md-flag">{sinProv} caso{sinProv > 1 ? "s" : ""} sin provincia precisada por la fuente.</div>}
                </>
              )}
            </aside>
          </div>
          {caso && <CasoCard caso={caso} onClose={() => setSelCaso(null)} />}
        </section>
      )}

      {/* ══ 4 · LA MÁQUINA ══ */}
      {tab === "maquina" && (
        <section className="panel">
          <div className="card-h">{sistema.titulo}</div>
          <div className="card-sub">{sistema.intro}</div>
          <div className="ley-flow">
            {(sistema.leyes || []).map((e, i) => (
              <div className="ley" key={i}>
                <div className="ley-rail">
                  <span className="ley-dot" />
                  {i < sistema.leyes.length - 1 && <span className="ley-line" />}
                </div>
                <div className="ley-body">
                  <div className="ley-year">{e.anio}</div>
                  <div className="ley-title">{e.titulo}</div>
                  <div className="ley-txt">{e.texto}</div>
                </div>
              </div>
            ))}
          </div>
          <div className="cargas-h">Lo que soporta el recluta</div>
          <div className="cargas">
            {(sistema.cargas || []).map((c) => (
              <div className="carga" key={c.id}>
                <div className="carga-t">{c.titulo}</div>
                <div className="carga-x">{c.texto}</div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* ══ 5 · CARNE DE CAÑÓN ══ */}
      {tab === "canon" && (
        <section className="panel">
          <div className="card-h">{cc.titulo}</div>
          <div className="card-sub">{cc.intro}</div>
          <div className="seg">
            <button className={"seg-b" + (frente === "rusia" ? " on" : "")} onClick={() => setFrente("rusia")}>Rusia / Ucrania · 2023</button>
            <button className={"seg-b" + (frente === "angola" ? " on" : "")} onClick={() => setFrente("angola")}>Angola · 1975–1991</button>
          </div>

          {frente === "rusia" && cc.rusia && (
            <>
              <div className="paygap">
                <div className="pg-h">Lo que se ofrecía frente a lo que se gana en Cuba</div>
                <PayBar label="Contrato ruso (promesa anual)" val={cc.rusia.salarioRusiaAnual} max={cc.rusia.salarioRusiaAnual} col={C.green} />
                <PayBar label="Salario medio en Cuba (anual, 2023)" val={cc.rusia.salarioCubaAnual} max={cc.rusia.salarioRusiaAnual} col={CAT.accidente.c} />
                <div className="pg-note">
                  Una diferencia de <b>{Math.round(cc.rusia.salarioRusiaAnual / cc.rusia.salarioCubaAnual)}×</b>.
                  Más un seguro de {usd(cc.rusia.seguroMuerte)} que se paga a la familia <b>si el recluta muere</b>.
                </div>
              </div>
              <div className="num-grid">
                <div className="num"><div className="num-n">{fmt(cc.rusia.listaIntercept)}</div><div className="num-l">pasaportes en la lista filtrada (The Intercept)</div></div>
                <div className="num"><div className="num-n">{fmt(cc.rusia.rastreados)}</div><div className="num-l">reclutas rastreados por la FDHC</div></div>
                <div className="num"><div className="num-n">{fmt(cc.rusia.avispasNegras)}</div><div className="num-l">posibles fuerzas especiales «Avispas Negras»</div></div>
                <div className="num"><div className="num-n">{fmt(cc.rusia.detenidos)}</div><div className="num-l">detenidos en Cuba ({cc.rusia.procesados})</div></div>
              </div>
              <div className="penas">
                <div className="pena"><span className="pena-k">Reclutar para un ejército extranjero</span><span className="pena-v">{cc.rusia.penaReclutar}</span></div>
                <div className="pena"><span className="pena-k">Mercenarismo</span><span className="pena-v">{cc.rusia.penaMercenarismo}</span></div>
              </div>
              <div className="readout"><p>{cc.rusia.nota}</p></div>
            </>
          )}

          {frente === "angola" && cc.angola && (
            <>
              <div className="paygap">
                <div className="pg-h">Lo que Angola pagaba por cada soldado frente a lo que el soldado recibía (mensual)</div>
                <PayBar label="Angola pagaba a Cuba, por soldado" val={cc.angola.pagoAngolaSoldadoMes} max={cc.angola.pagoAngolaSoldadoMes} col={C.green} />
                <PayBar label="El soldado recibía" val={cc.angola.pagoSoldadoMes} max={cc.angola.pagoAngolaSoldadoMes} col={CAT.asesinato.c} />
                <div className="pg-note">
                  El Estado embolsaba la diferencia: se estima que Cuba ingresó entre {usd(cc.angola.ingresosMinAnual)}M
                  y {usd(cc.angola.ingresosMaxAnual)}M al año durante {cc.angola.anios} años.
                </div>
              </div>
              <div className="num-grid">
                <div className="num"><div className="num-n">{fmt(cc.angola.militares)}</div><div className="num-l">militares cubanos ({cc.angola.periodo})</div></div>
                <div className="num"><div className="num-n">{fmt(cc.angola.civiles)}</div><div className="num-l">cooperantes civiles</div></div>
                <div className="num"><div className="num-n">{fmt(cc.angola.muertos)}</div><div className="num-l">muertos oficiales ({cc.angola.civilesMuertos} civiles)</div></div>
                <div className="num"><div className="num-n">169</div><div className="num-l">municipios con entierros en la «Operación Tributo» (1989)</div></div>
              </div>
              <div className="readout"><p>{cc.angola.nota}</p></div>
            </>
          )}
        </section>
      )}

      {/* ══ 6 · ENCUESTA ══ */}
      {tab === "encuesta" && (
        <section className="panel">
          <div className="card-h">Tu lectura</div>
          <div className="card-sub">Sin registro, sin datos personales. Solo se cuentan los votos{HAS_SUPA ? "." : " en este dispositivo."}</div>
          {(data.encuesta || []).map((q) => {
            const counts = { ...(live[q.id] || {}) };
            (q.opts || []).forEach((o) => { counts[o.id] = (counts[o.id] || 0) + (o.seed || 0); });
            const total = Object.values(counts).reduce((a, b) => a + b, 0) || 1;
            const voted = votos[q.id];
            return (
              <div className="poll" key={q.id}>
                <div className="poll-q">{q.q}</div>
                {(q.opts || []).map((o) => {
                  const pct = Math.round((counts[o.id] / total) * 100);
                  const mine = voted === o.id;
                  return (
                    <button key={o.id} className={"opt" + (voted ? " done" : "") + (mine ? " mine" : "")}
                      onClick={() => vote(q.id, o.id)} disabled={!!voted}>
                      <span className="opt-fill" style={{ width: voted ? `${pct}%` : "0%" }} />
                      <span className="opt-t">{o.t}</span>
                      {voted && <span className="opt-p">{pct}%</span>}
                    </button>
                  );
                })}
                {voted && <div className="poll-total">{fmt(total)} respuestas</div>}
              </div>
            );
          })}
        </section>
      )}

      <footer className="ft">
        <div>{data.meta && data.meta.fuentePrincipal}</div>
        <div className="ft-mut">
          Esfuerzo inicial en progreso · el costo real se sabe mayor · reconstrucción documental, no
          determinación judicial · Yamacoa · {data.meta && data.meta.actualizado}
        </div>
      </footer>
    </div>
  );
}

/* ── Barra de comparación de pago ─────────────────────────────────────────── */
function PayBar({ label, val, max, col }) {
  const w = Math.max(0.6, (val / max) * 100);
  return (
    <div className="pbar">
      <div className="pbar-l">{label}</div>
      <div className="pbar-track">
        <div className="pbar-fill" style={{ width: `${w}%`, background: col }} />
        <span className="pbar-v">{usd(val)}</span>
      </div>
    </div>
  );
}

/* ── Ficha de caso ────────────────────────────────────────────────────────── */
function CasoCard({ caso, onClose }) {
  const cCol = catCol(caso.cat);
  return (
    <div className="caso-card" style={{ borderLeftColor: cCol }}>
      <button className="cc-x" onClick={onClose} aria-label="cerrar">✕</button>
      <div className="cc-top">
        <span className="cc-tag" style={{ background: cCol + "22", color: cCol }}>{CAT[caso.cat] ? CAT[caso.cat].l : caso.cat}</span>
        <span className="cc-date">{caso.fecha}{caso.fechaAprox ? " (aprox.)" : ""}</span>
        {caso.menor && <span className="cc-menor">menor de edad</span>}
      </div>
      <div className="cc-name">{caso.nombre}{caso.edad != null ? <span className="cc-age">, {caso.edad} años</span> : null}</div>
      {caso.lugar && <div className="cc-meta">{caso.lugar}</div>}
      {caso.detalle ? <p className="cc-txt">{caso.detalle}</p> :
        <p className="cc-txt cc-mut">Caso del Anexo de Archivo Cuba; ficha individual en su base de datos.</p>}
    </div>
  );
}

/* ── Tooltip ──────────────────────────────────────────────────────────────── */
function CatTip({ active, payload }) {
  if (!active || !payload || !payload.length) return null;
  const d = payload[0];
  return <div className="tip"><div className="tip-row"><span>{d.name}</span><b>{fmt(d.value)}</b></div></div>;
}

/* ── CSS ──────────────────────────────────────────────────────────────────── */
const CSS = `
.smo{--bg:${C.bg};--panel:${C.panel};--line:${C.line};--ink:${C.ink};--mut:${C.mut};--gr:${C.green};--grh:${C.greenHi};--faint:${C.faint};
  background:var(--bg); color:var(--ink); font-family:'Archivo',system-ui,sans-serif;
  padding:clamp(16px,4vw,40px); max-width:1180px; margin:0 auto; line-height:1.5;}
.smo *{box-sizing:border-box;}
.smo b{font-weight:700;}
.eyebrow{font-family:'IBM Plex Mono',monospace; font-size:11px; letter-spacing:.24em; color:var(--gr); text-transform:uppercase; margin-bottom:14px;}
.title{font-size:clamp(34px,7vw,72px); font-weight:900; letter-spacing:-.02em; line-height:.95; margin:0 0 18px;}
.title span{color:var(--gr);}
.sub{max-width:770px; color:#CBE0D0; font-size:clamp(14px,1.6vw,17px); margin:0 0 26px;}
.kpis{display:grid; grid-template-columns:repeat(auto-fit,minmax(170px,1fr)); gap:14px; margin-bottom:20px;}
.kpi{background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:16px;}
.kpi-n{font-family:'IBM Plex Mono',monospace; font-size:32px; font-weight:600; color:var(--gr); line-height:1;}
.kpi-l{font-size:12.5px; color:#B2C6B8; margin-top:8px;}
.kpi-s{font-family:'IBM Plex Mono',monospace; font-size:10.5px; color:var(--mut); letter-spacing:.06em; margin-top:6px; text-transform:uppercase;}
.warn{background:rgba(51,194,122,.08); border:1px solid rgba(51,194,122,.30); border-radius:10px; padding:12px 14px; font-size:13px; color:#CDEAD8; margin-bottom:16px;}
.stamp{font-family:'IBM Plex Mono',monospace; font-size:10.5px; letter-spacing:.06em; color:var(--mut); text-transform:uppercase;}

.tabs{display:flex; flex-wrap:wrap; gap:6px; margin:28px 0 22px; border-bottom:1px solid var(--line); padding-bottom:14px;}
.tab{background:transparent; border:1px solid var(--line); color:var(--mut); font-family:'IBM Plex Mono',monospace; font-size:12px; padding:8px 13px; border-radius:20px; cursor:pointer; transition:.15s;}
.tab:hover{color:var(--ink); border-color:rgba(51,194,122,.45);}
.tab.on{background:var(--gr); color:#06231a; border-color:var(--gr); font-weight:600;}

.panel{animation:fade .3s ease;}
@keyframes fade{from{opacity:0; transform:translateY(6px);}to{opacity:1; transform:none;}}
.card-h{font-size:19px; font-weight:800; margin-bottom:4px;}
.card-sub{font-size:13.5px; color:var(--mut); margin-bottom:18px; max-width:820px;}
.grid2{display:grid; grid-template-columns:1fr 1fr; gap:16px;}
.card{background:var(--panel); border:1px solid var(--line); border-radius:14px; padding:18px;}
.chart{margin:6px -6px 0;}
.readout{background:var(--panel); border:1px solid var(--line); border-left:3px solid var(--gr); border-radius:10px; padding:16px 18px; margin-top:22px; font-size:14px; color:#CBE0D0;}
.readout p{margin:0;}

.legend{display:flex; flex-wrap:wrap; gap:7px; margin-top:10px;}
.lg-btn{display:flex; align-items:center; gap:7px; background:rgba(255,255,255,.03); border:1px solid var(--line); color:#CBE0D0; font-size:11.5px; padding:6px 9px; border-radius:20px; cursor:pointer;}
.lg-btn i{width:10px; height:10px; border-radius:3px;}
.lg-btn.on{border-color:var(--gr); background:rgba(51,194,122,.08);}

/* iceberg */
.ice{margin-top:6px;}
.ice-top{display:flex; align-items:center; gap:14px; background:rgba(51,194,122,.08); border:1px solid rgba(51,194,122,.28); border-radius:10px 10px 0 0; padding:16px;}
.ice-n{font-family:'IBM Plex Mono',monospace; font-size:44px; font-weight:600; color:var(--gr); line-height:1;}
.ice-l{font-size:13px; color:#CBE0D0;}
.ice-water{height:2px; background:repeating-linear-gradient(90deg,var(--grh),var(--grh) 8px,transparent 8px,transparent 16px);}
.ice-deep{background:rgba(255,255,255,.02); border:1px solid var(--line); border-top:none; border-radius:0 0 10px 10px; padding:18px 16px;}
.ice-deep-t{font-family:'IBM Plex Mono',monospace; font-size:22px; color:var(--mut); font-weight:600;}
.ice-deep-s{font-size:12.5px; color:var(--mut); margin-top:4px;}
.mini-stats{display:flex; flex-direction:column; gap:8px; margin-top:16px; font-size:13px; color:#CBE0D0;}
.mini-stats b{font-family:'IBM Plex Mono',monospace; color:var(--gr);} .mini-stats b.men{color:var(--grh);}

/* barra reproducción */
.map-bar{display:flex; align-items:center; gap:14px; flex-wrap:wrap; margin-bottom:12px;}
.play{background:var(--gr); color:#06231a; border:none; border-radius:8px; padding:9px 15px; font-family:'IBM Plex Mono',monospace; font-size:12px; font-weight:600; cursor:pointer; white-space:nowrap;}
.scrub{flex:1; min-width:180px; accent-color:var(--gr);}
.year-box{display:flex; align-items:baseline; gap:10px;}
.year-n{font-family:'IBM Plex Mono',monospace; font-size:22px; font-weight:600; color:var(--gr);}
.year-l{font-size:12px; color:var(--mut);}
.chips{display:flex; flex-wrap:wrap; gap:6px; margin-bottom:14px;}
.chip{background:transparent; border:1px solid var(--line); color:var(--mut); font-family:'IBM Plex Mono',monospace; font-size:11.5px; padding:6px 11px; border-radius:20px; cursor:pointer; transition:.15s;}
.chip.on{font-weight:600;}

/* timeline */
.tl-wrap{background:linear-gradient(180deg,#0E1712,#0A0F0C); border:1px solid var(--line); border-radius:14px; padding:12px 8px;}
.tl-svg{width:100%; height:auto; display:block;}
.tl-mes{fill:var(--mut); font-size:11px; font-family:'IBM Plex Mono',monospace;}
.tl-key{display:flex; flex-wrap:wrap; gap:16px; align-items:center; margin-top:10px; font-size:12px; color:#CBE0D0;}
.tl-key i{display:inline-block; margin-right:6px;}
.k-ring{width:12px; height:12px; border-radius:50%; border:1.5px solid var(--grh);}
.tl-key-mut{color:var(--mut);}
.tl-hint{font-size:13px; color:var(--mut); margin-top:16px; font-style:italic;}

/* caso card */
.caso-card{position:relative; background:var(--panel); border:1px solid var(--line); border-left:3px solid var(--gr); border-radius:12px; padding:18px 18px 16px; margin-top:16px;}
.cc-x{position:absolute; top:12px; right:12px; background:transparent; border:none; color:var(--mut); font-size:15px; cursor:pointer;}
.cc-top{display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-bottom:8px;}
.cc-tag{font-family:'IBM Plex Mono',monospace; font-size:10.5px; letter-spacing:.06em; text-transform:uppercase; padding:3px 9px; border-radius:20px;}
.cc-date{font-family:'IBM Plex Mono',monospace; font-size:12px; color:var(--mut);}
.cc-menor{font-family:'IBM Plex Mono',monospace; font-size:10px; color:#06231a; background:var(--grh); padding:2px 8px; border-radius:20px; text-transform:uppercase; letter-spacing:.06em;}
.cc-name{font-size:20px; font-weight:800;}
.cc-age{font-weight:600; color:var(--mut); font-size:16px;}
.cc-meta{font-size:12.5px; color:var(--grh); font-family:'IBM Plex Mono',monospace; margin:2px 0 10px;}
.cc-txt{font-size:14px; color:#CBE0D0; margin:0;} .cc-txt.cc-mut{color:var(--mut); font-style:italic;}

/* mapa */
.map-stage{display:grid; grid-template-columns:1.55fr 1fr; gap:16px; align-items:start;}
.map-wrap{background:linear-gradient(180deg,#0E1712,#0A0F0C); border:1px solid var(--line); border-radius:14px; padding:10px;}
.map-svg{width:100%; height:auto; display:block;}
.map-detail{background:var(--panel); border:1px solid var(--line); border-radius:14px; padding:18px; min-height:260px;}
.md-year{font-family:'IBM Plex Mono',monospace; font-size:11px; letter-spacing:.1em; text-transform:uppercase; color:var(--mut);}
.md-toll{display:flex; align-items:baseline; gap:8px; margin:6px 0 12px;}
.md-toll-n{font-family:'IBM Plex Mono',monospace; font-size:34px; font-weight:600; color:var(--gr);}
.md-toll-l{font-size:12px; color:var(--mut);}
.md-txt{font-size:13.5px; color:#CBE0D0; margin:0 0 12px;}
.md-flag{font-size:12.5px; color:#CDEAD8; background:rgba(51,194,122,.08); border:1px solid rgba(51,194,122,.24); border-radius:8px; padding:10px 12px;}
.prov-list{display:flex; flex-direction:column; gap:2px; margin-top:4px; max-height:320px; overflow:auto;}
.pl-row{display:grid; grid-template-columns:auto 1fr auto; gap:9px; align-items:center; background:transparent; border:none; border-bottom:1px solid var(--line); padding:8px 2px; cursor:pointer; text-align:left; color:var(--ink);}
.pl-row:hover{background:rgba(255,255,255,.03);}
.pl-row i{width:9px; height:9px; border-radius:50%;}
.pl-name{font-size:13px;}
.pl-date{font-family:'IBM Plex Mono',monospace; font-size:11px; color:var(--mut);}

/* la máquina: ley flow */
.ley-flow{margin:6px 0 26px;}
.ley{display:grid; grid-template-columns:24px 1fr; gap:14px;}
.ley-rail{display:flex; flex-direction:column; align-items:center;}
.ley-dot{width:13px; height:13px; border-radius:50%; background:var(--greenDeep,#0F2E20); border:2px solid var(--gr); margin-top:5px; flex:none;}
.ley-line{flex:1; width:2px; background:linear-gradient(var(--gr),rgba(51,194,122,.2)); margin:3px 0;}
.ley-body{padding-bottom:20px;}
.ley-year{font-family:'IBM Plex Mono',monospace; font-size:16px; font-weight:600; color:var(--gr);}
.ley-title{font-size:15px; font-weight:800; margin:1px 0 4px;}
.ley-txt{font-size:13px; color:#CBE0D0; max-width:760px;}
.cargas-h{font-family:'IBM Plex Mono',monospace; font-size:12px; letter-spacing:.08em; text-transform:uppercase; color:var(--gr); margin:6px 0 12px;}
.cargas{display:grid; grid-template-columns:repeat(auto-fit,minmax(240px,1fr)); gap:12px;}
.carga{background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:15px;}
.carga-t{font-size:14.5px; font-weight:800; margin-bottom:6px;}
.carga-x{font-size:12.5px; color:#CBE0D0;}

/* carne de cañón */
.seg{display:inline-flex; gap:4px; background:var(--panel2); border:1px solid var(--line); border-radius:10px; padding:4px; margin-bottom:20px;}
.seg-b{background:transparent; border:none; color:var(--mut); font-family:'IBM Plex Mono',monospace; font-size:12px; padding:8px 14px; border-radius:7px; cursor:pointer;}
.seg-b.on{background:var(--gr); color:#06231a; font-weight:600;}
.paygap{background:var(--panel); border:1px solid var(--line); border-radius:14px; padding:20px; margin-bottom:16px;}
.pg-h{font-size:14px; font-weight:700; margin-bottom:16px;}
.pbar{margin-bottom:14px;}
.pbar-l{font-size:12.5px; color:#CBE0D0; margin-bottom:6px;}
.pbar-track{position:relative; height:30px; background:rgba(255,255,255,.04); border-radius:7px; overflow:hidden;}
.pbar-fill{height:100%; border-radius:7px; min-width:3px; transition:width .6s ease;}
.pbar-v{position:absolute; top:50%; left:12px; transform:translateY(-50%); font-family:'IBM Plex Mono',monospace; font-size:13px; font-weight:600; color:#0a0f0c; mix-blend-mode:screen;}
.pg-note{font-size:13px; color:var(--mut); margin-top:6px;} .pg-note b{color:var(--gr); font-family:'IBM Plex Mono',monospace;}
.num-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:12px; margin-bottom:16px;}
.num{background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:15px;}
.num-n{font-family:'IBM Plex Mono',monospace; font-size:28px; font-weight:600; color:var(--gr); line-height:1;}
.num-l{font-size:12px; color:#B2C6B8; margin-top:6px;}
.penas{display:flex; flex-direction:column; gap:8px; margin-bottom:16px;}
.pena{display:flex; justify-content:space-between; gap:14px; align-items:center; background:var(--panel); border:1px solid var(--line); border-radius:10px; padding:12px 15px;}
.pena-k{font-size:13px; color:#CBE0D0;}
.pena-v{font-family:'IBM Plex Mono',monospace; font-size:12.5px; color:var(--grh); text-align:right;}

/* encuesta */
.poll{background:var(--panel); border:1px solid var(--line); border-radius:14px; padding:20px; margin-bottom:16px;}
.poll-q{font-size:15px; font-weight:700; margin-bottom:14px;}
.opt{position:relative; display:flex; align-items:center; gap:10px; width:100%; text-align:left; background:rgba(255,255,255,.03); border:1px solid var(--line); border-radius:10px; padding:12px 14px; margin-bottom:9px; cursor:pointer; color:var(--ink); font-size:13.5px; overflow:hidden; transition:.15s;}
.opt:hover:not(:disabled){border-color:rgba(51,194,122,.45);}
.opt:disabled{cursor:default;}
.opt-fill{position:absolute; inset:0 auto 0 0; background:rgba(51,194,122,.16); transition:width .5s ease; z-index:0;}
.opt.mine .opt-fill{background:rgba(51,194,122,.30);}
.opt-t{position:relative; z-index:1; flex:1;}
.opt-p{position:relative; z-index:1; font-family:'IBM Plex Mono',monospace; font-size:12.5px; color:var(--grh);}
.opt.mine{border-color:var(--gr);}
.poll-total{font-family:'IBM Plex Mono',monospace; font-size:11px; color:var(--mut); margin-top:4px;}

/* tip */
.tip{background:#08100B; border:1px solid var(--line); border-radius:8px; padding:8px 11px; font-size:12px;}
.tip-row{display:flex; justify-content:space-between; gap:16px; color:#CBE0D0;} .tip-row b{color:var(--ink);}

/* footer */
.ft{margin-top:40px; border-top:1px solid var(--line); padding-top:18px; font-size:12.5px; color:#CBE0D0;}
.ft-mut{color:var(--mut); font-size:11.5px; margin-top:6px;}

@media(max-width:820px){
  .grid2{grid-template-columns:1fr;}
  .map-stage{grid-template-columns:1fr;}
}
`;
